// Builds self-contained .jsx files from games in this folder.
//
//   node tools/make-standalone.js [Game.jsx | --all]
//
// Every #include is replaced with the file's contents (each file once), so the
// result runs from anywhere without lib/ next to it.
// Output: standalone/<name>_standalone.jsx
// Edit the source game and rebuild - never edit the generated file.

const fs = require("fs");
const path = require("path");

const ROOT = path.resolve(__dirname, "..");
const STANDALONE_DIR = path.join(ROOT, "standalone");

const ALL_GAMES = [
    "2048.jsx",
    "Arkanoid.jsx",
    "BoulderDash.jsx",
    "PacMan.jsx",
    "Snake.jsx",
    "SpaceInvaders.jsx",
    "Tetris.jsx",
    "LodeRunner.jsx",
    "Xonix.jsx",
    "Bomberman.jsx",
    "BattleCity.jsx",
    "Play Arcade.jsx"
];

function buildStandalone(file) {
    const fullSource = path.join(ROOT, file);
    if (!fs.existsSync(fullSource)) {
        console.error("Game file not found: " + fullSource);
        return false;
    }

    fs.mkdirSync(STANDALONE_DIR, { recursive: true });
    const OUT = path.join(STANDALONE_DIR, path.basename(file).replace(/\.jsx$/i, "") + "_standalone.jsx");
    const seen = new Set();

    function inline(relPath) {
        const full = path.join(ROOT, relPath);
        const text = fs.readFileSync(full, "utf8").replace(/^\uFEFF/, "");
        const out = [];
        for (const line of text.split(/\r?\n/)) {
            const m = line.match(/^\s*#include\s+"([^"]+)"\s*$/);
            if (!m) { out.push(line); continue; }

            const inc = path.join(path.dirname(relPath), m[1]).replace(/\\/g, "/");
            const key = path.normalize(inc);
            if (seen.has(key)) { out.push("// [inlined earlier] " + inc); continue; }

            seen.add(key);
            out.push("// ==== begin " + inc + " ====");
            out.push(inline(inc).replace(/\s+$/, ""));
            out.push("// ==== end " + inc + " ====");
        }
        return out.join("\n");
    }

    const body = inline(file).replace(/^\s*#target[^\n]*\n/m, "");
    const name = path.basename(file, ".jsx").toUpperCase();

    const header = [
        "#target illustrator",
        "// " + name + " - standalone build.",
        "// Everything from lib/ is inlined below, so this file runs on its own:",
        "// File > Scripts > Other Script... and that is all it needs.",
        "// Generated from " + file + " + lib/ by tools/make-standalone.js.",
        "// Edit the source game, then rebuild - do not edit this file.",
        ""
    ].join("\n");

    const result = header + body + "\n";
    // Illustrator decodes a BOM-less .jsx as Windows-1252, so any non-ASCII text
    // (the i18n strings) needs the BOM or the UI turns to mojibake.
    const needsBom = Buffer.from(result, "utf8").some((b) => b > 127);
    fs.writeFileSync(OUT, (needsBom ? "\uFEFF" : "") + result, "utf8");

    const bytes = Buffer.from(result, "utf8");
    console.log("wrote " + path.relative(ROOT, OUT).replace(/\\/g, "/"));
    console.log("  lines     " + result.split("\n").length);
    console.log("  bytes     " + bytes.length);
    console.log("  non-ASCII " + bytes.filter((b) => b > 127).length);
    console.log("  inlined   " + seen.size + " files");
    console.log("  includes  " + (result.match(/^\s*#include/mg) || []).length);
    return true;
}

const arg = process.argv[2];

if (!arg || arg === "--all") {
    console.log("Building standalone bundles into standalone/ (" + ALL_GAMES.length + " scripts)...\n");
    for (const g of ALL_GAMES) {
        buildStandalone(g);
        console.log("");
    }
} else {
    buildStandalone(arg);
}
